<title>Vulgar · 艾瑞凡</title>
<style>
*{margin:0;padding:0;box-sizing:border-box}
:root{
--bg:#0b0704;--gold:#c9a84c;--gold2:#8a7030;--parch:#cdbb88;--parch2:#e0d1a3;
--ink:#24180d;--wood:#6b3b1b;--wood2:#8b5429;--blood:#8b2500
}
body{
min-height:100vh;overflow:hidden;color:var(--ink);
font-family:"Microsoft YaHei","SimSun",serif;
background:radial-gradient(circle at 50% 26%,#2b1b0f 0%,#0b0704 62%,#030201 100%)
}
body:before{
content:"";position:fixed;inset:0;z-index:9999;pointer-events:none;
background:repeating-linear-gradient(0deg,transparent 0 2px,rgba(220,190,120,.025) 2px 4px)
}
#map-toggle,.legend-toggle{display:none}

/* 宝箱折叠态 */
.chest-stage{
position:fixed;inset:0;z-index:50;display:grid;place-items:center;
background:radial-gradient(circle at 50% 48%,rgba(201,168,76,.16),transparent 35%);
transition:.45s ease
}
#map-toggle:checked~.chest-stage{opacity:0;visibility:hidden;transform:scale(.95)}
.chest-card{text-align:center;filter:drop-shadow(0 35px 45px rgba(0,0,0,.78))}
.chest{position:relative;display:block;width:310px;height:220px;cursor:pointer;animation:float 3.4s ease-in-out infinite}
@keyframes float{0%,100%{transform:translateY(0)}50%{transform:translateY(-8px)}}
.chest:hover{transform:translateY(-7px) scale(1.025)}
.chest-glow{position:absolute;left:50%;top:76px;transform:translateX(-50%);width:220px;height:38px;background:radial-gradient(ellipse,rgba(255,220,90,.62),rgba(255,220,90,.15),transparent 72%);filter:blur(7px)}
.chest-lid{
position:absolute;left:18px;top:22px;width:274px;height:94px;border-radius:140px 140px 18px 18px;
background:linear-gradient(90deg,rgba(255,255,255,.08),transparent 22%,transparent 78%,rgba(0,0,0,.28)),linear-gradient(#91582b,#5d3118 76%,#311708);
border:5px solid #211108;box-shadow:inset 0 11px 0 rgba(255,225,140,.08),inset 0 -14px 0 rgba(0,0,0,.28)
}
.chest-lid:before,.chest-lid:after{content:"";position:absolute;top:-5px;width:34px;height:98px;background:linear-gradient(#3a342c,#17120e);border:2px solid #0d0906}
.chest-lid:before{left:52px}.chest-lid:after{right:52px}
.chest-body{
position:absolute;left:0;bottom:0;width:310px;height:134px;border-radius:16px 16px 28px 28px;
background:linear-gradient(90deg,rgba(255,255,255,.07),transparent 18%,transparent 82%,rgba(0,0,0,.32)),repeating-linear-gradient(90deg,transparent 0 48px,rgba(0,0,0,.16) 48px 54px),linear-gradient(#8b5128,#653519 55%,#3c1d0c);
border:6px solid #211209;box-shadow:inset 0 12px 0 rgba(255,220,130,.07),inset 0 -18px 0 rgba(0,0,0,.25)
}
.chest-band{position:absolute;left:0;top:106px;width:310px;height:29px;background:linear-gradient(#4a4438,#17130e);border-top:2px solid #0b0805;border-bottom:2px solid #0b0805}
.chest-lock{
position:absolute;left:50%;top:90px;transform:translateX(-50%);width:60px;height:70px;border-radius:8px 8px 15px 15px;
background:linear-gradient(135deg,#f3dc85,#b58b2c 48%,#5d4616);border:4px solid #2a2110;
box-shadow:0 6px 14px rgba(0,0,0,.55),inset 0 3px 0 rgba(255,255,255,.25);z-index:3
}
.chest-lock:after{content:"";position:absolute;left:22px;top:28px;width:10px;height:21px;background:#2a2110;border-radius:6px}
.chest-title{margin-top:26px;color:var(--gold);font-size:30px;letter-spacing:6px;text-shadow:0 0 18px rgba(201,168,76,.4),0 3px 8px #000}
.chest-sub{margin-top:8px;color:#9f8650;font-size:13px;letter-spacing:3px}
.chest-hint{margin-top:18px;color:#d8c38a;font-size:15px;letter-spacing:2px;animation:pulse 1.8s infinite}
@keyframes pulse{0%,100%{opacity:.55}50%{opacity:1}}

/* 展开地图 */
.page{
position:fixed;inset:0;z-index:20;display:grid;grid-template-rows:auto 1fr;
background:linear-gradient(180deg,#1a1208,#0b0704);opacity:0;visibility:hidden;transform:scale(1.04);transition:.45s ease
}
#map-toggle:checked~.page{opacity:1;visibility:visible;transform:scale(1)}
.header{
position:relative;text-align:center;padding:18px 84px 15px 34px;
background:linear-gradient(180deg,rgba(30,22,12,.98),rgba(14,9,5,.96));
border-bottom:1px solid rgba(201,168,76,.34);box-shadow:0 12px 34px rgba(0,0,0,.55)
}
.header:before{content:"─── ◆ ───";display:block;color:var(--gold2);font-size:13px;letter-spacing:6px;margin-bottom:6px;opacity:.65}
.header h1{font-size:30px;color:var(--gold);letter-spacing:7px;text-shadow:0 0 18px rgba(201,168,76,.32),0 2px 5px #000}
.header p{margin-top:4px;color:#a89060;font-size:12px;letter-spacing:3px}
.close-map{
