border:2px solid var(--gold2);color:var(--gold);background:rgba(18,12,7,.75);font-size:25px;box-shadow:0 6px 18px rgba(0,0,0,.45)
}
.close-map:hover{background:rgba(139,37,0,.45);color:#f2d98a}
.map-shell{position:relative;overflow:auto;background:radial-gradient(circle at 50% 50%,rgba(42,31,20,.32),transparent 60%)}
svg{display:block;min-width:2100px;min-height:1220px;width:100%;height:100%}

/* 地图色彩 */
.ocean{fill:#19150f}.deep-ocean{fill:#0c0906;opacity:.67}.sea-shelf{fill:none;stroke:rgba(190,150,90,.11);stroke-width:20}.sea-line{fill:none;stroke:rgba(210,185,120,.16);stroke-width:1.2;stroke-dasharray:5 8}
.continent{fill:#3c3120;stroke:#aa9362;stroke-width:2.2;filter:drop-shadow(0 0 16px rgba(0,0,0,.86))}
.land-detail{fill:none;stroke:rgba(115,92,55,.42);stroke-width:1.4}
.island{fill:#372b1c;stroke:#aa9362;stroke-width:1.25;filter:drop-shadow(0 0 8px rgba(0,0,0,.72))}
.ice{fill:rgba(190,215,220,.13)}.taiga{fill:rgba(65,90,55,.18)}.steppe{fill:rgba(130,126,58,.19)}.desert{fill:rgba(188,138,64,.22)}
.humanland{fill:rgba(80,115,45,.23)}.highland{fill:rgba(128,82,42,.24)}.rainforest{fill:rgba(25,95,52,.26)}.plateau{fill:rgba(122,78,46,.27)}.riftzone{fill:rgba(139,37,0,.20)}
.mountain{fill:none;stroke:#6f5e45;stroke-width:4.2;stroke-linecap:round;stroke-linejoin:round;filter:drop-shadow(1px 2px 3px rgba(0,0,0,.55))}
.mountain2{fill:none;stroke:#5c4c37;stroke-width:2.2;stroke-linecap:round;stroke-linejoin:round}
.river{fill:none;stroke:#4a718f;stroke-width:2.8;stroke-linecap:round;stroke-linejoin:round;filter:drop-shadow(0 0 4px rgba(74,112,144,.48))}
.river2{fill:none;stroke:#3d6079;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round}
.route{fill:none;stroke:rgba(201,168,76,.38);stroke-width:1.7;stroke-dasharray:7 7}
.rift{fill:none;stroke:var(--blood);stroke-width:3.2;stroke-linecap:round;stroke-dasharray:8 5;filter:drop-shadow(0 0 8px rgba(139,37,0,.72))}
.label{
fill:rgba(205,187,136,.18);font-weight:700;letter-spacing:8px;font-size:27px;pointer-events:none;
paint-order:stroke;stroke:rgba(0,0,0,.25);stroke-width:2px
}
.label.small{font-size:18px;letter-spacing:4px}.label.sea{fill:rgba(160,140,96,.23);font-size:34px;letter-spacing:12px}
.fog{pointer-events:none}.fog rect,.fog ellipse{filter:url(#fogBlur)}

/* 图标 */
.city{cursor:pointer;outline:none}.city .pin{transition:.2s}.city text.name{
fill:#cdbb88;font-size:11px;paint-order:stroke;stroke:rgba(14,10,6,.92);stroke-width:4px;stroke-linejoin:round;opacity:.78;pointer-events:none
}
.city text.icon{font-size:17px;text-anchor:middle;dominant-baseline:middle;paint-order:stroke;stroke:#140c05;stroke-width:3px}
