function badgeClass(type,kind){
 if(kind==="port")return"badge-port";
 return{human:"badge-human",dwarf:"badge-dwarf",elf:"badge-elf",demon:"badge-demon",neutral:"badge-neutral"}[type]||"badge-geo"
}
function ns(t,a={}){const n=document.createElementNS("http://www.w3.org/2000/svg",t);Object.entries(a).forEach(([k,v])=>n.setAttribute(k,v));return n}
const layer=document.getElementById("marker-layer"),dock=document.getElementById("info-dock");

locations.forEach(([id,name,kind,type,x,y,lx,ly,badge,desc,lore])=>{
 const g=ns("g",{class:`city ${kind} ${type}`,"data-panel":id,transform:`translate(${x} ${y})`,tabindex:"0"});
 const pin=ns("circle",{class:"pin",r:kind==="capital"?8:kind==="geo"?5.3:kind==="landmark"?4.5:5.6});
 g.appendChild(pin);
 const icon=ns("text",{class:"icon",x:0,y:kind==="port"?1:0});icon.textContent=iconMap[kind]||"●";g.appendChild(icon);
 const txt=ns("text",{class:"name",x:lx,y:ly});txt.textContent=name;g.appendChild(txt);
 layer.appendChild(g);

 const s=document.createElement("section");s.className="info-panel";s.id="panel-"+id;
 s.innerHTML=`<div class="scroll-inner"><button class="close-info" type="button">×</button><h2>${name}</h2><div class="divider">── ◆ ──</div><span class="badge ${badgeClass(type,kind)}">${badge}</span><p>${desc}</p><p class="lore">${lore}</p></div>`;
 dock.appendChild(s);
});

const cities=document.querySelectorAll(".city[data-panel]");
const panels=document.querySelectorAll(".info-panel");
const def=document.getElementById("panel-default");
function show(id){
 panels.forEach(p=>p.classList.remove("active"));
 cities.forEach(c=>c.classList.remove("active"));
 document.getElementById("panel-"+id)?.classList.add("active");
 document.querySelector(`.city[data-panel="${id}"]`)?.classList.add("active");
}
function reset(){
 panels.forEach(p=>p.classList.remove("active"));
 cities.forEach(c=>c.classList.remove("active"));
 def.classList.add("active");
}
cities.forEach(c=>{
 c.onclick=()=>show(c.dataset.panel);
 c.onkeydown=e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();show(c.dataset.panel)}};
});
document.querySelectorAll(".close-info").forEach(b=>b.onclick=reset);
document.getElementById("map-toggle").addEventListener("change",e=>{if(!e.target.checked)reset()});
