.card small,.empty{color:rgba(255,242,220,.66);font-family:var(--ui);font-size:11px;line-height:1.5}
.memory-text{margin-top:6px;white-space:pre-wrap;color:rgba(255,242,220,.78);font:12px/1.6 var(--ui)}
.kv{display:flex;justify-content:space-between;gap:8px;padding:4px 0;border-bottom:1px dashed rgba(255,255,255,.12);font-size:12px}
.kv:last-child{border-bottom:0}.kv span:first-child{color:rgba(255,242,220,.66)}.kv span:last-child{color:#fff;font-weight:700;text-align:right}
.bar{margin-top:6px;height:8px;border-radius:999px;background:rgba(255,255,255,.08);overflow:hidden}
.fill{height:100%;border-radius:999px;background:linear-gradient(90deg,#5ad67d,#ffe66b,#ff6b6b);box-shadow:0 0 14px rgba(255,220,100,.3)}
.stage{display:grid;grid-template-columns:52px minmax(0,1fr) 52px;align-items:stretch;filter:drop-shadow(0 34px 56px rgba(0,0,0,.72))}
.rod{position:relative;min-height:620px;border-radius:999px;background:linear-gradient(90deg,rgba(255,255,255,.07),transparent 14%,rgba(0,0,0,.52) 78%),linear-gradient(90deg,var(--roller-a),var(--roller-b),var(--roller-a));box-shadow:inset 10px 0 20px rgba(255,255,255,.06),inset -16px 0 24px rgba(0,0,0,.72)}.rod.r{transform:scaleX(-1)}
.rod::before,.rod::after{content:"";position:absolute;left:-7px;right:-7px;height:34px;border-radius:14px;background:linear-gradient(180deg,var(--metal-b),var(--metal-a) 55%,#1d1208);box-shadow:0 7px 16px rgba(0,0,0,.55),inset 0 2px rgba(255,255,255,.45)}.rod::before{top:-14px}.rod::after{bottom:-14px}.rod i{position:absolute;inset:18px 50%;width:2px;transform:translateX(-50%);background:rgba(0,0,0,.35);box-shadow:1px 0 rgba(255,255,255,.12)}
.paper{position:relative;min-height:620px;padding:42px clamp(20px,5vw,68px);background:linear-gradient(90deg,rgba(0,0,0,.16),transparent 6%,transparent 94%,rgba(0,0,0,.16)),radial-gradient(circle at 50% 0,rgba(255,255,255,.35),transparent 38%),var(--paper-noise),var(--paper);clip-path:var(--shape);box-shadow:inset 28px 0 34px rgba(65,32,10,.16),inset -28px 0 34px rgba(65,32,10,.16),inset 0 0 0 1px color-mix(in srgb,var(--paper-edge) 48%,transparent)}
.paper::before{content:"";position:absolute;inset:18px 24px;pointer-events:none;border:1px solid color-mix(in srgb,var(--paper-edge) 62%,transparent);border-radius:10px;opacity:.85}
.paper::after{content:var(--motif);position:absolute;inset:auto 30px 20px;text-align:center;font-size:42px;letter-spacing:.35em;color:var(--accent);opacity:.08;pointer-events:none}
.reader{position:relative;z-index:2;color:var(--ink);line-height:1.86;text-rendering:optimizeLegibility}.reader p{margin:0 0 1.05em}.narrative{text-indent:2em;text-align:justify}.plain-block{margin-bottom:1.05em;white-space:pre-wrap}.quote-red{color:#bb1f1f;font-weight:800;text-shadow:0 0 1px rgba(187,31,31,.16)}.paren-blue{color:#1f5ea8;font-weight:650}
.dialogue{margin:16px 0;display:grid;grid-template-columns:auto 1fr;gap:10px;padding:12px 14px;border-left:4px solid var(--accent);background:rgba(255,255,255,.18);box-shadow:inset 0 0 0 1px rgba(0,0,0,.04)}.speaker{color:var(--accent);font-weight:900;white-space:nowrap}.words{color:var(--ink)}
.inline-status{display:flex;flex-wrap:wrap;gap:10px;margin:0 0 18px;padding:12px;border:1px solid color-mix(in srgb,var(--paper-edge) 55%,transparent);background:rgba(255,255,255,.18);transition:.35s ease}.night .inline-status{background:rgba(12,18,36,.78);border-color:rgba(162,184,255,.24);color:#eef3ff}.pill{display:inline-flex;gap:6px;align-items:center;padding:5px 9px;border-radius:999px;background:rgba(0,0,0,.055);color:var(--ink);font-family:var(--ui);font-size:.86em}.night .pill{background:rgba(255,255,255,.08);color:#eef3ff}
.fold{margin:18px 0;border:1px solid color-mix(in srgb,var(--paper-edge) 62%,transparent);background:rgba(255,255,255,.14);border-radius:10px;overflow:hidden}.fold summary{cursor:pointer;list-style:none;padding:11px 14px;color:var(--accent);font-weight:850;font-family:var(--ui);user-select:none}.fold summary::-webkit-details-marker{display:none}.fold-body{padding:12px 14px;border-top:1px dashed color-mix(in srgb,var(--paper-edge) 55%,transparent);white-space:pre-wrap}
body.hide-restricted .restricted-fold{display:none}
.float-tip{position:fixed;right:18px;bottom:18px;z-index:50;max-width:280px;display:none;padding:12px 14px;border-radius:14px;background:rgba(0,0,0,.78);color:#fff2df;font:13px/1.6 var(--ui);box-shadow:0 16px 40px rgba(0,0,0,.4)}.float-tip.show{display:block;animation:openDrawer .22s ease}
.tree-card{grid-column:1/-1;padding:12px;border-radius:14px;border:1px solid rgba(255,255,255,.12);background:rgba(255,255,255,.06);box-shadow:inset 0 1px rgba(255,255,255,.08)}
.tree-head{display:flex;align-items:center;justify-content:space-between;gap:10px}
.tree-name{font:700 14px var(--ui);color:#fff3df}
.tree-brief{margin-top:4px;color:rgba(255,242,220,.68);font:11px/1.5 var(--ui)}
.tree-group{margin-top:10px;padding-top:10px;border-top:1px dashed rgba(255,255,255,.12)}
.tree-group b{display:block;margin-bottom:6px;color:#fff3df;font-size:12px}
.tree-list{display:grid;gap:6px}
.tree-item{padding:8px;border-radius:10px;background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.08)}
.tree-item strong{display:block;margin-bottom:2px;font-size:11px;color:#fff3df}
.tree-item span{display:block;color:rgba(255,242,220,.72);font:11px/1.4 var(--ui);white-space:pre-wrap}

/* 移动端适配及竖屏折叠规则 */
@media(max-width:900px){.command{grid-template-columns:1fr}.toolbar{justify-content:flex-start}}
@media(max-width:760px) and (orientation:portrait){
  body{padding:8px}
  .ext-info, .skybar{display:none !important} /* 极简适配：隐藏多余前缀内容与天气条 */
  .command{position:relative;top:auto;grid-template-columns:1fr;padding:10px;margin-bottom:12px;border-radius:12px}
  .title{font-size:22px;letter-spacing:.08em}
  .subtitle{font-size:11px}
  .panel-menu, .drawer-body{grid-template-columns:repeat(2,1fr);gap:6px;padding:10px}
  .drawer-head{padding:10px}
  .stage{grid-template-columns:1fr}
  .rod{min-height:30px;height:30px;border-radius:999px}.rod.r{transform:none}
  .rod::before,.rod::after{top:-6px;bottom:-6px;width:28px;height:auto;left:auto;right:auto}.rod::before{left:-10px}.rod::after{right:-10px}
  .rod i{inset:50% 16px auto;height:2px;width:auto;transform:translateY(-50%)}
  .paper{min-height:480px;clip-path:none;border-radius:6px;padding:32px 20px}
}
@media(max-width:760px) and (orientation:landscape){
  body{padding:12px}
  .skybar,.command{position:relative;top:auto}
  .stage{grid-template-columns:1fr}
  .rod{min-height:38px;height:38px;border-radius:999px}.rod.r{transform:none}
  .rod::before,.rod::after{top:-7px;bottom:-7px;width:34px;height:auto;left:auto;right:auto}.rod::before{left:-12px}.rod::after{right:-12px}
  .rod i{inset:50% 18px auto;height:2px;width:auto;transform:translateY(-50%)}
  .paper{min-height:520px;clip-path:none;border-radius:8px}
}
</style>
</head>
<body data-realm="human" class="hide-restricted">
<div class="campaign">
  <section class="skybar" id="skybar">
    <div class="sky-left">
      <div class="sky-icon" id="sky-icon">☀</div>
      <div class="sky-text">
        <strong id="sky-title">白昼巡行</strong>
        <span id="sky-desc">时间、天气与世界色调正在同步记录</span>
      </div>
    </div>
    <div class="sky-right">
      <span class="sky-pill" id="sky-time">--:--</span>
      <span class="sky-pill" id="sky-period">昼</span>
      <span class="sky-pill" id="sky-weather">天气：晴朗</span>
    </div>
  </section>

  <header class="command">
    <div class="brand">
      <div class="sig">✦</div>
      <div class="brand-copy">
        <div class="title"><span class="ext-info">Vulgar · </span>艾瑞凡</div>
        <div class="subtitle">作者 · 北辰星<span class="ext-info">「星黑」 A world born from blood, mapped by will, and haunted by memory.</span></div>
      </div>
    </div>
    <div class="toolbar">
      <button class="tool" id="open-panel">总览面板</button>
      <div class="font-ctl" title="字号调节">
        <button id="fs-minus">−</button>
        <span id="fs-value">16</span>
        <button id="fs-plus">+</button>
      </div>
      <div class="palette" title="主题切换">
        <button class="theme-dot t-human active" data-realm="human" title="人族"></button>
        <button class="theme-dot t-elf" data-realm="elf" title="精灵"></button>
        <button class="theme-dot t-dwarf" data-realm="dwarf" title="矮人"></button>
        <button class="theme-dot t-demon" data-realm="demon" title="魔族"></button>
        <button class="theme-dot t-ocean" data-realm="ocean" title="大海"></button>
      </div>
    </div>
  </header>

  <section class="drawer" id="drawer">
    <div class="drawer-head">
      <strong id="drawer-title">总览面板</strong>
      <div class="drawer-actions">
        <button class="panel-nav" id="drawer-back" style="display:none;">返回上一级</button>
        <span id="drawer-count">9 项</span>
      </div>
    </div>
    <div class="drawer-body" id="drawer-body"></div>
  </section>

  <main class="stage">
    <aside class="rod"><i></i></aside>
    <article class="paper"><div class="reader" id="reader">$1</div></article>
    <aside class="rod r"><i></i></aside>
  </main>
</div>

<div class="float-tip" id="tip"></div>

<script>
(function(){
  const body=document.body, root=document.documentElement, reader=document.getElementById('reader'), drawer=document.getElementById('drawer');
  const drawerTitle=document.getElementById('drawer-title'), drawerCount=document.getElementById('drawer-count'), drawerBody=document.getElementById('drawer-body'), drawerBack=document.getElementById('drawer-back'), tip=document.getElementById('tip'), openPanelBtn=document.getElementById('open-panel');
  const skyIcon=document.getElementById('sky-icon'), skyTitle=document.getElementById('sky-title'), skyDesc=document.getElementById('sky-desc'), skyTime=document.getElementById('sky-time'), skyPeriod=document.getElementById('sky-period'), skyWeather=document.getElementById('sky-weather');

  const equipmentSlots=['头部','上衣','下衣','脚部','手部','单手武器','双手武器','法杖类武器','魔法技能'];
  const restrictedKeys=['逻辑','逻辑数据','隐藏逻辑','敏感','敏感内容','系统记录','内心想法','隐藏信息','幕后信息'];
  const statusFields=['等级','当前位置','生命值','魔力值','衣着','外貌','政治与威望','通缉/恶名值','职业'];
  const physFields=['饱食度＆水分','体力','营养价值评估','疾病','体温','睡眠','伤势','中毒','药效','卫生'];

  const panelItems=[
    {key:'memory',title:'记忆总结',desc:'极简重要变动记录'},
    {key:'status',title:'状态栏',desc:'点击查看四级人物面板'},
    {key:'physiology',title:'生理',desc:'体征及伤病隐患'},
    {key:'characters',title:'在场角色',desc:'周遭NPC与人际脉络'},
    {key:'inventory',title:'背包',desc:'持有物品无限动态扩展'},
    {key:'quests',title:'任务',desc:'委托与主线任务线索'},
    {key:'lore',title:'百科',desc:'世界观地理物种科普'},
    {key:'factions',title:'政治声望',desc:'各大势力派系好感度'},
    {key:'restricted',title:'限制信息',desc:'受控内容及逻辑日志'}
  ];

  const store={memory:[],statusProfiles:[],physiology:[],characters:[],inventory:[],quests:[],lore:[],factions:[],restricted:[]};
  let drawerView='menu', currentStatusProfileIndex=-1;
  const rxCache={}; // 正则预编译缓存，提升性能

  function save(k,v){try{localStorage.setItem(k,v)}catch(e){}}
  function load(k,f){try{return localStorage.getItem(k)||f}catch(e){return f}}
  function esc(t){return String(t||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')}
  function showTip(t){tip.textContent=t;tip.classList.add('show');clearTimeout(showTip.t);showTip.t=setTimeout(()=>tip.classList.remove('show'),1600)}
  function splitLines(t){return String(t||'').replace(/\r/g,'').trim().split(/\n+/).map(v=>v.trim()).filter(Boolean)}
  function splitParagraphs(t){return String(t||'').replace(/\r/g,'').trim().split(/\n\s*\n/).map(v=>v.trim()).filter(Boolean)}
  function splitFields(t){return String(t||'').trim().split(/[，,]/).map(v=>v.trim()).filter(Boolean)}
  function parseKvLine(l){const i=String(l).search(/[:：=]/);return i<0?{key:String(l).trim(),value:''}:{key:String(l).slice(0,i).trim(),value:String(l).slice(i+1).trim()}}
  function card(t,d,e){return `<div class="card"><b>${t||'未命名'}</b><small>${d||''}</small>${e||''}</div>`}
  function meter(v){let n=parseInt(String(v).replace(/[^\d-]/g,''),10);if(Number.isNaN(n))return'';return `<div class="bar"><div class="fill" style="width:${Math.max(0,Math.min(100,n))}%"></div></div>`}
  function dataName(d,f){return d['角色']||d['姓名']||d['名字']||d['角色名']||d['名称']||f||'主角'}
  function trimSum(t,m=200){const r=String(t||'').replace(/\s+/g,' ').trim();return r.length<=m?r:r.slice(0,m-1)+'…'}
  function isRes(k){return restrictedKeys.includes(String(k||'').trim())}

  function getStatusProfile(name,brief){
    const sName=(name||'主角').trim()||'主角';
    let p=store.statusProfiles.find(i=>i.name===sName);
    if(!p){p={name:sName,brief:brief||'角色状态栏',summary:[],stats:[],equipment:{},extras:[]};store.statusProfiles.push(p);}
    else if(brief&&p.brief==='角色状态栏')p.brief=brief;
    return p;
  }
  function addProfileItem(pN,g,t,d,b){
    const p=getStatusProfile(pN,b), i={title:t||'未命名',desc:d||'',meter:meter(d)};
    if(g==='equipment')p.equipment[t]=d||'未装备'; else if(g==='summary')p.summary.push(i); else if(g==='stats')p.stats.push(i); else p.extras.push(i);
  }
  function renderGroup(items){return items.length?`<div class="tree-list">${items.map(i=>`<div class="tree-item"><strong>${esc(i.title)}</strong><span>${esc(i.desc)}</span>${i.meter||''}</div>`).join('')}</div>`:'<div class="empty">暂无</div>'}

  function renderMenu(){
    drawerView='menu'; drawerTitle.textContent='总览面板'; drawerCount.textContent=panelItems.length+' 项'; drawerBack.style.display='none'; drawerBody.className='panel-menu';
    drawerBody.innerHTML=panelItems.map(i=>`<div class="panel-entry" data-entry="${i.key}"><b>${i.title}</b><span>${i.desc}</span></div>`).join('');
    drawer.classList.add('show'); drawerBody.querySelectorAll('[data-entry]').forEach(n=>n.addEventListener('click',()=>renderContent(n.dataset.entry)));
  }

  function renderStatusList(){
    drawerView='status-list'; drawerTitle.textContent='状态栏'; drawerCount.textContent=store.statusProfiles.length+' 角色'; drawerBack.style.display='inline-flex'; drawerBody.className='panel-menu';
    drawerBody.innerHTML=store.statusProfiles.length?store.statusProfiles.map((p,i)=>`<div class="panel-entry" data-sp="${i}"><b>${esc(p.name)}</b><span>${esc(p.brief||'查看状态')}</span></div>`).join(''):'<div class="empty">无状态数据</div>';
    drawer.classList.add('show'); drawerBody.querySelectorAll('[data-sp]').forEach(n=>n.addEventListener('click',()=>renderStatusDetail(+n.dataset.sp)));
  }

  function renderStatusDetail(i){
    const p=store.statusProfiles[i]; if(!p)return renderStatusList();
    drawerView='status-detail'; drawerTitle.textContent=p.name; drawerCount.textContent='四级详情'; drawerBack.style.display='inline-flex'; drawerBody.className='drawer-body';
    drawerBody.innerHTML=`<div class="tree-card"><div class="tree-head"><div class="tree-name">${esc(p.name)}</div><button class="tree-toggle" data-bk="1">返回</button></div><div class="tree-brief">${esc(p.brief)}</div>
      <div class="tree-group"><b>基本状态</b>${renderGroup([].concat(p.summary,p.stats,p.extras))}</div><div class="tree-group"><b>装备</b>${renderGroup(equipmentSlots.map(s=>({title:s,desc:p.equipment[s]||'未装备'})))}</div></div>`;
    drawerBody.querySelector('[data-bk]').addEventListener('click',renderStatusList);
  }

  function renderContent(type){
    if(type==='status')return renderStatusList();
    drawerView=type; const d=store[type]||[], tM={memory:'记忆',physiology:'生理',characters:'在场',inventory:'背包',quests:'任务',lore:'百科',factions:'政治',restricted:'限制'};
    drawerTitle.textContent=tM[type]||'面板'; drawerCount.textContent=d.length+' 项'; drawerBack.style.display='inline-flex'; drawerBody.className='drawer-body';
    drawerBody.innerHTML=d.length?d.join(''):'<div class="empty">暂无数据</div>'; drawer.classList.add('show');
  }

  openPanelBtn.addEventListener('click',()=>{(drawer.classList.contains('show')&&drawerView==='menu')?drawer.classList.remove('show'):renderMenu()});
  drawerBack.addEventListener('click',()=>drawerView==='status-detail'?renderStatusList():renderMenu());

  const themeBtns=document.querySelectorAll('.theme-dot');
  function setRealm(r){body.dataset.realm=r;themeBtns.forEach(b=>b.classList.toggle('active',b.dataset.realm===r));save('ae-rlm',r);showTip('主题已切换')}
  themeBtns.forEach(b=>b.addEventListener('click',()=>setRealm(b.dataset.realm))); setRealm(load('ae-rlm','human'));

  let fs=parseInt(load('ae-fs','16'),10)||16; const fsVal=document.getElementById('fs-value');
  function setFs(v){fs=Math.max(12,Math.min(24,v));root.style.setProperty('--fs',fs+'px');fsVal.textContent=fs;save('ae-fs',fs)}
  document.getElementById('fs-minus').addEventListener('click',()=>setFs(fs-1)); document.getElementById('fs-plus').addEventListener('click',()=>setFs(fs+1)); setFs(fs);

  let resVis=load('ae-res','0')==='1'; body.classList.toggle('hide-restricted',!resVis);

  // 极简提取引擎
  function extTag(s,tg){
    if(!rxCache[tg]) rxCache[tg]=new RegExp(`<${tg}>([\\s\\S]*?)<\\/${tg}>`,'gi');
    const blks=[]; const c=s.replace(rxCache[tg],(_,inr)=>{blks.push(inr);return `\n<!--B:${tg}:${blks.length-1}-->\n`}); return {c,blks};
  }
  function pData(inr){const d={}; splitLines(inr).forEach(l=>{const p=parseKvLine(l);d[p.key]=p.value}); return d;}

  function pushStatus(d,pN){
    const iA=['⭐','📍','❤️','🔮','👕','👁','🏛','⚠','⚒'], n=pN||dataName(d,'主角'), b=d['职业']||d['身份']||d['状态']||d['当前位置']||'状态';
    statusFields.forEach((f,i)=>{if(d[f])addProfileItem(n,'stats',iA[i]+' '+f,d[f],b)});
    equipmentSlots.forEach(s=>{if(d[s])addProfileItem(n,'equipment',s,d[s],b)});
    Object.keys(d).forEach(k=>{if(statusFields.includes(k)||physFields.includes(k)||equipmentSlots.includes(k)||['角色','姓名','名字','名称','身份','状态'].includes(k)||isRes(k))return;addProfileItem(n,'summary',k,d[k],b)});
  }
  function pushPhys(d){const iA=['🍞','💪','🥗','🦠','🌡','🛌','🩸','☠','💊','🧼']; physFields.forEach((n,i)=>{if(d[n])store.physiology.push(card(iA[i]+' '+n,esc(d[n]),meter(d[n])))});}

  // 高性能离线DOM组装
  function buildHtml(w, tgs){
    let h=w.replace(/<!--B:USER_STATUS:(\d+)-->/g,(_,i)=>`<div class="inline-status">${splitFields(tgs.user_status.blks[+i]||'').filter(x=>!isRes(parseKvLine(x).key)).map((f,id)=>`<span class="pill">${['⭐','📍','❤️','🔮','👕','👁','🏛','⚠','⚒'][id]||'✦'} ${esc(f)}</span>`).join('')}</div>`);
    ['MEMORY_SUMMARY','MEMORY','SCENE','CHARACTERS','NPC_STATUS','PHYSIOLOGY','FACTIONS','CALENDAR'].forEach(n=>h=h.replace(new RegExp(`<!--B:${n}:(\\d+)-->`,'g'),''));
    h=h.replace(/<!--B:INVENTORY:(\d+)-->/g,(_,i)=>`<details class="fold"><summary>🎒 背包</summary><div class="fold-body">${esc(splitLines(tgs.inventory.blks[+i]||'').join('\n'))}</div></details>`);
    h=h.replace(/<!--B:QUEST_LOG:(\d+)-->/g,(_,i)=>`<details class="fold"><summary>📜 任务记录</summary><div class="fold-body">${esc(splitLines(tgs.quest_log.blks[+i]||'').join('\n'))}</div></details>`);
    h=h.replace(/<!--B:LORE:(\d+)-->/g,(_,i)=>`<details class="fold"><summary>📚 内置百科</summary><div class="fold-body">${esc((tgs.lore.blks[+i]||'').trim())}</div></details>`);
    h=h.replace(/<!--B:LOGIC:(\d+)-->/g,(_,i)=>`<details class="fold restricted-fold"><summary>📋 限制信息</summary><div class="fold-body">${esc((tgs.logic.blks[+i]||'').trim())}</div></details>`);
    h=h.replace(/<!--B:NSFW:(\d+)-->/g,(_,i)=>`<details class="fold restricted-fold"><summary>⚠ 限制信息</summary><div class="fold-body">${esc((tgs.nsfw.blks[+i]||'').trim())}</div></details>`);
