*{box-sizing:border-box;margin:0;padding:0}
body{min-height:100vh;color:var(--ink);font-family:var(--font);font-size:var(--fs);padding:22px;overflow-x:hidden;background:radial-gradient(circle at 50% -10%,var(--sky-a),transparent 44%),radial-gradient(circle at 12% 82%,var(--sky-b),transparent 34%),linear-gradient(135deg,var(--world-bg),var(--world-2));transition:background .7s ease,color .4s ease,filter .4s ease}
body.dawn{--sky-a:#ffd18a;--sky-b:rgba(255,112,80,.35);filter:saturate(1.08)}
body.morning{--sky-a:#fff3b0;--sky-b:rgba(110,190,255,.28);filter:brightness(1.04)}
body.noon{--sky-a:#fffbe0;--sky-b:rgba(255,220,100,.35);filter:brightness(1.1) saturate(1.04)}
body.afternoon{--sky-a:#ffb36d;--sky-b:rgba(190,90,45,.36);filter:saturate(1.12)}
body.night{--sky-a:#15224a;--sky-b:rgba(80,92,170,.28);filter:brightness(.88)}
body::before{content:var(--motif);position:fixed;inset:auto 0 8vh 0;z-index:0;text-align:center;font-size:clamp(54px,13vw,190px);letter-spacing:.15em;color:#fff;opacity:.055;filter:blur(.2px) drop-shadow(0 0 24px var(--glow));pointer-events:none;white-space:pre}
body::after{content:"";position:fixed;inset:0;z-index:0;pointer-events:none;background:linear-gradient(90deg,rgba(255,255,255,.04),transparent 18%,transparent 82%,rgba(255,255,255,.04)),radial-gradient(circle at 50% 50%,transparent 42%,rgba(0,0,0,.5));mix-blend-mode:screen;opacity:.8}
.campaign{position:relative;z-index:2;max-width:1240px;margin:0 auto}
.skybar,.command{position:sticky;z-index:35;border:1px solid rgba(255,255,255,.16);box-shadow:0 16px 44px rgba(0,0,0,.32);backdrop-filter:blur(12px)}
.skybar{top:0;display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:12px;padding:10px 14px;border-radius:16px;background:linear-gradient(90deg,var(--bar-a),var(--bar-b));color:var(--bar-ink)}
.dawn{--bar-a:rgba(255,225,178,.9);--bar-b:rgba(255,198,157,.66);--bar-ink:#4b2511}
.morning{--bar-a:rgba(255,252,220,.9);--bar-b:rgba(215,238,255,.68);--bar-ink:#26361e}
.noon{--bar-a:rgba(255,255,245,.94);--bar-b:rgba(255,240,180,.7);--bar-ink:#3b2a12}
.afternoon{--bar-a:rgba(255,210,156,.9);--bar-b:rgba(255,160,110,.65);--bar-ink:#44200d}
.night{--bar-a:rgba(10,16,30,.9);--bar-b:rgba(18,28,46,.75);--bar-ink:#eef3ff}
.sky-left{display:flex;align-items:center;gap:10px;min-width:0}
.sky-icon{width:34px;height:34px;border-radius:50%;display:grid;place-items:center;font-size:18px;background:radial-gradient(circle at 35% 35%,#fff,var(--accent-2));box-shadow:0 0 18px rgba(255,255,255,.2),inset 0 1px 4px rgba(255,255,255,.24)}
.sky-text strong{display:block;font-family:var(--ui);font-size:13px;letter-spacing:.08em}
.sky-text span{font:12px var(--ui);opacity:.8}
.sky-right{display:flex;gap:10px;flex-wrap:wrap;justify-content:flex-end}
.sky-pill{padding:6px 10px;border-radius:999px;background:rgba(0,0,0,.08);font:12px var(--ui)}.night .sky-pill{background:rgba(255,255,255,.08)}
.command{top:60px;display:grid;grid-template-columns:minmax(420px,1.65fr) minmax(280px,1fr);gap:16px;align-items:center;margin-bottom:18px;padding:14px 16px;border-radius:18px;background:linear-gradient(180deg,rgba(255,255,255,.18),rgba(255,255,255,.06));border-color:color-mix(in srgb,var(--accent) 45%,#000)}
.night .command{background:linear-gradient(180deg,rgba(16,18,28,.92),rgba(8,10,18,.82))}
.brand{display:flex;gap:14px;align-items:flex-start;min-width:0;max-width:100%}
.sig{width:52px;height:52px;flex:0 0 52px;display:grid;place-items:center;border-radius:16px;color:var(--paper);font-size:20px;background:radial-gradient(circle at 35% 20%,var(--accent-2),transparent 28%),linear-gradient(135deg,var(--accent),#1a0b08);box-shadow:0 0 24px var(--glow),inset 0 0 0 1px rgba(255,255,255,.25)}
.brand-copy{min-width:0;flex:1}
.title{color:#f7ead8;font-weight:800;letter-spacing:.12em;line-height:1.05;font-size:clamp(24px,2.2vw,34px);text-shadow:0 2px 14px rgba(0,0,0,.8)}
.subtitle{margin-top:6px;color:rgba(255,245,225,.78);font-size:13px;line-height:1.7;font-family:var(--ui);max-width:760px}
.ext-info{display:inline}
.toolbar{display:flex;flex-wrap:wrap;gap:8px;justify-content:flex-end;align-items:center}
.tool,.theme-dot,.font-ctl button,.panel-nav,.tree-toggle{border:1px solid rgba(255,255,255,.2);background:rgba(0,0,0,.2);color:#f6ead8;border-radius:12px;cursor:pointer;transition:.2s ease}
.tool,.panel-nav{padding:8px 11px;font-family:var(--ui);font-size:13px}
.tool:hover,.tool.active,.panel-nav:hover,.panel-nav.active,.tree-toggle:hover{transform:translateY(-1px);background:var(--accent);border-color:rgba(255,255,255,.35);box-shadow:0 0 18px var(--glow)}
.font-ctl{display:flex;align-items:center;overflow:hidden;border-radius:12px;border:1px solid rgba(255,255,255,.2);background:rgba(0,0,0,.18)}
.font-ctl button{border:0;border-radius:0;width:31px;height:31px;font-weight:800}
.font-ctl span{min-width:42px;text-align:center;color:#f6ead8;font:12px var(--ui)}
.palette{display:flex;gap:6px;align-items:center;padding-left:8px;border-left:1px solid rgba(255,255,255,.2)}
.theme-dot{width:28px;height:28px;border-radius:10px}
.theme-dot.active{transform:translateY(-2px) scale(1.05);border-color:#fff;box-shadow:0 0 18px var(--glow),inset 0 2px 6px rgba(255,255,255,.5)}
.t-human{background:linear-gradient(135deg,#d8b36b,#8b1d1d)}.t-elf{background:linear-gradient(135deg,#c9e7b4,#1c7a46)}.t-dwarf{background:linear-gradient(135deg,#ff9840,#2b2928)}.t-demon{background:linear-gradient(135deg,#c46296,#180711)}.t-ocean{background:linear-gradient(135deg,#7bd5dc,#0b4255)}
.drawer{display:none;margin:-6px 0 16px;border:1px solid rgba(255,255,255,.16);border-radius:20px;background:rgba(12,10,8,.68);color:#f2e5d3;box-shadow:0 24px 60px rgba(0,0,0,.38);backdrop-filter:blur(14px);overflow:hidden}.drawer.show{display:block;animation:openDrawer .22s ease}@keyframes openDrawer{from{opacity:0;transform:translateY(-8px)}to{opacity:1;transform:translateY(0)}}
.drawer-head{display:flex;justify-content:space-between;align-items:center;gap:10px;padding:12px 14px;border-bottom:1px solid rgba(255,255,255,.12);font-family:var(--ui)}
.drawer-head strong{font-size:14px;letter-spacing:.04em}
.drawer-actions{display:flex;gap:8px;flex-wrap:wrap;justify-content:flex-end}
.drawer-body, .panel-menu{display:grid;grid-template-columns:repeat(auto-fill,minmax(140px,1fr));gap:8px;padding:12px}
.panel-entry{padding:10px;border-radius:14px;border:1px solid rgba(255,255,255,.12);background:rgba(255,255,255,.06);cursor:pointer;transition:.2s ease;box-shadow:inset 0 1px rgba(255,255,255,.08)}
.panel-entry:hover{transform:translateY(-2px);background:rgba(255,255,255,.1);border-color:rgba(255,255,255,.24)}
.panel-entry b{display:block;color:#fff3df;font-size:13px;margin-bottom:4px}
.panel-entry span{display:block;color:rgba(255,242,220,.68);font:11px/1.5 var(--ui)}
.card{border:1px solid rgba(255,255,255,.12);border-radius:14px;padding:10px;background:rgba(255,255,255,.055);min-height:unset}
.card b{display:block;color:#fff3df;margin-bottom:5px;font-size:13px}
.card small,.empty{color:rgba(255,242,220,.66);font-family:var(--ui);font-size:11px;line-height:1.5}
.memory-text{margin-top:6px;white-space:pre-wrap;color:rgba(255,242,220,.78);font:12px/1.6 var(--ui)}
.kv{display:flex;justify-content:space-between;gap:8px;padding:4px 0;border-bottom:1px dashed rgba(255,255,255,.12);font-size:12px}
.kv:last-child{border-bottom:0}.kv span:first-child{color:rgba(255,242,220,.66)}.kv span:last-child{color:#fff;font-weight:700;text-align:right}
.bar{margin-top:6px;height:8px;border-radius:999px;background:rgba(255,255,255,.08);overflow:hidden}
.fill{height:100%;border-radius:999px;background:linear-gradient(90deg,#5ad67d,#ffe66b,#ff6b6b);box-shadow:0 0 14px rgba(255,220,100,.3)}
.stage{display:grid;grid-template-columns:52px minmax(0,1fr) 52px;align-items:stretch;filter:drop-shadow(0 34px 56px rgba(0,0,0,.72))}
.rod{position:relative;min-height:620px;border-radius:999px;background:linear-gradient(90deg,rgba(255,255,255,.07),transparent 14%,rgba(0,0,0,.52) 78%),linear-gradient(90deg,var(--roller-a),var(--roller-b),var(--roller-a));box-shadow:inset 10px 0 20px rgba(255,255,255,.06),inset -16px 0 24px rgba(0,0,0,.72)}.rod.r{transform:scaleX(-1)}
.rod::before,.rod::after{content:"";position:absolute;left:-7px;right:-7px;height:34px;border-radius:14px;background:linear-gradient(180deg,var(--metal-b),var(--metal-a) 55%,#1d1208);box-shadow:0 7px 16px rgba(0,0,0,.55),inset 0 2px rgba(255,255,255,.45)}.rod::before{top:-14px}.rod::after{bottom:-14px}.rod i{position:absolute;inset:18px 50%;width:2px;transform:translateX(-50%);background:rgba(0,0,0,.35);box-shadow:1px 0 rgba(255,255,255,.12)}
.paper{position:relative;min-height:620px;padding:42px clamp(20px,5vw,68px);background:linear-gradient(90deg,rgba(0,0,0,.16),transparent 6%,transparent 94%,rgba(0,0,0,.16)),radial-gradient(circle at 50% 0,rgba(255,255,255,.35),transparent 38%),var(--paper-noise),var(--paper);clip-path:var(--shape);box-shadow:inset 28px 0 34px rgba(65,32,10,.16),inset -28px 0 34px rgba(65,32,10,.16),inset 0 0 0 1px color-mix(in srgb,var(--paper-edge) 48%,transparent)}
.paper::before{content:"";position:absolute;inset:18px 24px;pointer-events:none;border:1px solid color-mix(in srgb,var(--paper-edge) 62%,transparent);border-radius:10px;opacity:.85}
.paper::after{content:var(--motif);position:absolute;inset:auto 30px 20px;text-align:center;font-size:42px;letter-spacing:.35em;color:var(--accent);opacity:.08;pointer-events:none}
.reader{position:relative;z-index:2;color:var(--ink);line-height:1.86;text-rendering:optimizeLegibility}.reader p{margin:0 0 1.05em}.narrative{text-indent:2em;text-align:justify}.plain-block{margin-bottom:1.05em;white-space:pre-wrap}.quote-red{color:#bb1f1f;font-weight:800;text-shadow:0 0 1px rgba(187,31,31,.16)}.paren-blue{color:#1f5ea8;font-weight:650}
.dialogue{margin:16px 0;display:grid;grid-template-columns:auto 1fr;gap:10px;padding:12px 14px;border-left:4px solid var(--accent);background:rgba(255,255,255,.18);box-shadow:inset 0 0 0 1px rgba(0,0,0,.04)}.speaker{color:var(--accent);font-weight:900;white-space:nowrap}.words{color:var(--ink)}
.inline-status{display:flex;flex-wrap:wrap;gap:10px;margin:0 0 18px;padding:12px;border:1px solid color-mix(in srgb,var(--paper-edge) 55%,transparent);background:rgba(255,255,255,.18);transition:.35s ease}.night .inline-status{background:rgba(12,18,36,.78);border-color:rgba(162,184,255,.24);color:#eef3ff}.pill{display:inline-flex;gap:6px;align-items:center;padding:5px 9px;border-radius:999px;background:rgba(0,0,0,.055);color:var(--ink);font-family:var(--ui);font-size:.86em}.night .pill{background:rgba(255,255,255,.08);color:#eef3ff}
.fold{margin:18px 0;border:1px solid color-mix(in srgb,var(--paper-edge) 62%,transparent);background:rgba(255,255,255,.14);border-radius:10px;overflow:hidden}.fold summary{cursor:pointer;list-style:none;padding:11px 14px;color:var(--accent);font-weight:850;font-family:var(--ui);user-select:none}.fold summary::-webkit-details-marker{display:none}.fold-body{padding:12px 14px;border-top:1px dashed color-mix(in srgb,var(--paper-edge) 55%,transparent);white-space:pre-wrap}
body.hide-restricted .restricted-fold{display:none}
.float-tip{position:fixed;right:18px;bottom:18px;z-index:50;max-width:280px;display:none;padding:12px 14px;border-radius:14px;background:rgba(0,0,0,.78);color:#fff2df;font:13px/1.6 var(--ui);box-shadow:0 16px 40px rgba(0,0,0,.4)}.float-tip.show{display:block;animation:openDrawer .22s ease}
.tree-card{grid-column:1/-1;padding:12px;border-radius:14px;border:1px solid rgba(255,255,255,.12);background:rgba(255,255,255,.06);box-shadow:inset 0 1px rgba(255,255,255,.08)}
.tree-head{display:flex;align-items:center;justify-content:space-between;gap:10px}
.tree-name{font:700 14px var(--ui);color:#fff3df}
.tree-brief{margin-top:4px;color:rgba(255,242,220,.68);font:11px/1.5 var(--ui)}
.tree-group{margin-top:10px;padding-top:10px;border-top:1px dashed rgba(255,255,255,.12)}
.tree-group b{display:block;margin-bottom:6px;color:#fff3df;font-size:12px}
.tree-list{display:grid;gap:6px}
.tree-item{padding:8px;border-radius:10px;background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.08)}
.tree-item strong{display:block;margin-bottom:2px;font-size:11px;color:#fff3df}
.tree-item span{display:block;color:rgba(255,242,220,.72);font:11px/1.4 var(--ui);white-space:pre-wrap}

/* 移动端适配及竖屏折叠规则 */
@media(max-width:900px){.command{grid-template-columns:1fr}.toolbar{justify-content:flex-start}}
@media(max-width:760px) and (orientation:portrait){
  body{padding:8px}
  .ext-info, .skybar{display:none !important} /* 极简适配：隐藏多余前缀内容与天气条 */
  .command{position:relative;top:auto;grid-template-columns:1fr;padding:10px;margin-bottom:12px;border-radius:12px}
  .title{font-size:22px;letter-spacing:.08em}
  .subtitle{font-size:11px}
  .panel-menu, .drawer-body{grid-template-columns:repeat(2,1fr);gap:6px;padding:10px}
  .drawer-head{padding:10px}
  .stage{grid-template-columns:1fr}
  .rod{min-height:30px;height:30px;border-radius:999px}.rod.r{transform:none}
  .rod::before,.rod::after{top:-6px;bottom:-6px;width:28px;height:auto;left:auto;right:auto}.rod::before{left:-10px}.rod::after{right:-10px}
  .rod i{inset:50% 16px auto;height:2px;width:auto;transform:translateY(-50%)}
  .paper{min-height:480px;clip-path:none;border-radius:6px;padding:32px 20px}
}
@media(max-width:760px) and (orientation:landscape){
  body{padding:12px}
  .skybar,.command{position:relative;top:auto}
  .stage{grid-template-columns:1fr}
  .rod{min-height:38px;height:38px;border-radius:999px}.rod.r{transform:none}
  .rod::before,.rod::after{top:-7px;bottom:-7px;width:34px;height:auto;left:auto;right:auto}.rod::before{left:-12px}.rod::after{right:-12px}
  .rod i{inset:50% 18px auto;height:2px;width:auto;transform:translateY(-50%)}
  .paper{min-height:520px;clip-path:none;border-radius:8px}
}
</style>
</head>
<body data-realm="human" class="hide-restricted">
<div class="campaign">
  <section class="skybar" id="skybar">
